create extension if not exists pgcrypto;
create table public.schools(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,school_id uuid references public.schools(id),full_name text not null default '',role text not null default 'student' check(role in ('admin','teacher','student','parent')),created_at timestamptz default now());
create table public.academic_sessions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id),name text not null,active boolean default false);
create table public.classes(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id),name text not null,session_id uuid references public.academic_sessions(id));
create table public.subjects(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id),name text not null);
create table public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),class_id uuid not null references public.classes(id),unique(student_id,class_id));
create table public.teacher_assignments(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles(id),class_id uuid not null references public.classes(id),subject_id uuid not null references public.subjects(id),unique(teacher_id,class_id,subject_id));
create table public.parent_students(parent_id uuid not null references public.profiles(id),student_id uuid not null references public.profiles(id),primary key(parent_id,student_id));
create table public.lesson_notes(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles(id),class_id uuid references public.classes(id),subject_id uuid references public.subjects(id),title text not null,body text not null default '',transcript text,created_at timestamptz default now());
create table public.exams(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles(id),class_id uuid references public.classes(id),subject_id uuid references public.subjects(id),title text not null,duration_minutes integer not null default 60,published boolean not null default false,created_at timestamptz default now());
create table public.questions(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id) on delete cascade,position integer not null,question_type text not null check(question_type in ('mcq','theory')),prompt text not null,options jsonb,answer_key jsonb,marks numeric(7,2) not null default 1,unique(exam_id,position));
create table public.exam_attempts(id uuid primary key default gen_random_uuid(),exam_id uuid not null references public.exams(id),student_id uuid not null references public.profiles(id),started_at timestamptz default now(),submitted_at timestamptz,score numeric(8,2));
create table public.student_answers(id uuid primary key default gen_random_uuid(),attempt_id uuid not null references public.exam_attempts(id) on delete cascade,question_id uuid not null references public.questions(id),answer jsonb,awarded_marks numeric(7,2),unique(attempt_id,question_id));
create table public.attendance(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),class_id uuid not null references public.classes(id),day date not null,status text not null check(status in ('present','absent','late','excused')),unique(student_id,class_id,day));
create table public.assessments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),subject_id uuid not null references public.subjects(id),session_id uuid not null references public.academic_sessions(id),term integer not null check(term between 1 and 3),ca_score numeric(6,2),exam_score numeric(6,2),teacher_comment text,unique(student_id,subject_id,session_id,term));
create table public.report_cards(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),session_id uuid not null references public.academic_sessions(id),term integer not null check(term between 1 and 3),approved_by uuid references public.profiles(id),approved_at timestamptz,remarks text,unique(student_id,session_id,term));
create table public.announcements(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id),author_id uuid not null references public.profiles(id),title text not null,body text not null,created_at timestamptz default now());
do $$ declare t text; begin foreach t in array array['schools','profiles','academic_sessions','classes','subjects','enrollments','teacher_assignments','parent_students','lesson_notes','exams','questions','exam_attempts','student_answers','attendance','assessments','report_cards','announcements'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profile_self_read on public.profiles for select to authenticated using (id=(select auth.uid()));
create policy profile_self_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()) and role=(select p.role from public.profiles p where p.id=(select auth.uid())) and school_id is not distinct from (select p.school_id from public.profiles p where p.id=(select auth.uid())));
create policy own_notes on public.lesson_notes for all to authenticated using(teacher_id=(select auth.uid())) with check(teacher_id=(select auth.uid()));
create policy own_exams on public.exams for all to authenticated using(teacher_id=(select auth.uid())) with check(teacher_id=(select auth.uid()));
create policy own_attempts_read on public.exam_attempts for select to authenticated using(student_id=(select auth.uid()));
create policy own_attempts_insert on public.exam_attempts for insert to authenticated with check(student_id=(select auth.uid()));
